// Only the public publishable/anon key belongs in the browser. RLS protects data.
const CONFIG='aeroping-cloud-v1',SESSION='aeroping-session-v1';
export function cloudConfig(){try{return JSON.parse(localStorage.getItem(CONFIG)||'null');}catch{return null;}}
export function configureCloud(url,key){const u=new URL(url);if(u.protocol!=='https:'||!u.hostname.endsWith('.supabase.co')||u.pathname!=='/'||u.search||u.hash||u.username||u.password)throw Error('Use a URL HTTPS do projeto, como https://seuprojeto.supabase.co.');if(!key||key.length<20)throw Error('Informe a chave pública publishable ou anon.');try{const data=JSON.parse(atob(key.split('.')[1]));if(data.role==='service_role')throw Error('Nunca use uma chave service_role no navegador.');}catch(e){if(e.message.includes('service_role'))throw e;}if(key.startsWith('sb_secret_'))throw Error('Use uma chave pública, nunca uma chave secreta.');localStorage.setItem(CONFIG,JSON.stringify({url:u.origin,key}));sessionStorage.removeItem(SESSION);}
function session(){try{return JSON.parse(sessionStorage.getItem(SESSION)||'null');}catch{return null;}}
export const signedIn=()=>!!session();
export async function signIn(email,password){const c=cloudConfig();if(!c)throw Error('Configure o Supabase primeiro.');const r=await fetch(`${c.url}/auth/v1/token?grant_type=password`,{method:'POST',headers:{apikey:c.key,'Content-Type':'application/json'},body:JSON.stringify({email,password})});const d=await r.json();if(!r.ok)throw Error('Não foi possível entrar. Confira o e-mail e a senha das contas criadas no Supabase.');sessionStorage.setItem(SESSION,JSON.stringify(d));return membership();}
async function accessToken(){let s=session();if(!s)throw Error('Entre na conta para sincronizar.');if(s.expires_at*1000<Date.now()+60000){const c=cloudConfig();const r=await fetch(`${c.url}/auth/v1/token?grant_type=refresh_token`,{method:'POST',headers:{apikey:c.key,'Content-Type':'application/json'},body:JSON.stringify({refresh_token:s.refresh_token})});if(!r.ok){sessionStorage.removeItem(SESSION);throw Error('Sua sessão expirou. Entre novamente.');}s=await r.json();sessionStorage.setItem(SESSION,JSON.stringify(s));}return s.access_token;}
async function request(path,options={}){const c=cloudConfig(),token=await accessToken();const r=await fetch(`${c.url}/rest/v1/${path}`,{...options,headers:{apikey:c.key,Authorization:`Bearer ${token}`,'Content-Type':'application/json',...options.headers}});if(!r.ok){throw Error(r.status===401?'Sua sessão expirou. Entre novamente.':'Não foi possível sincronizar. Confira a conexão, o SQL e as permissões do Supabase.');}return r.status===204?null:r.json();}
export async function membership(){const id=session()?.user?.id;const rows=await request(`members?select=household_id&user_id=eq.${encodeURIComponent(id)}`);if(rows.length!==1)throw Error('Sua conta precisa pertencer a um casal no Supabase. Siga o guia de instalação.');return rows[0].household_id;}
export async function readCloud(){const id=await membership();const rows=await request(`radar_state?select=payload,revision&household_id=eq.${encodeURIComponent(id)}`);return {household:id,payload:rows[0]?.payload??null,revision:rows[0]?.revision??0};}
export async function writeCloud(payload,revision){const id=await membership();const result=await request('rpc/save_radar',{method:'POST',body:JSON.stringify({p_household:id,p_payload:payload,p_revision:revision})});if(!result.ok){const e=new Error('O outro dispositivo atualizou os dados. Exporte suas alterações locais antes de carregar a versão do casal.');e.conflict=true;throw e;}return result.revision;}
export async function signOut(){const c=cloudConfig(),s=session();sessionStorage.removeItem(SESSION);if(c&&s)try{await fetch(`${c.url}/auth/v1/logout`,{method:'POST',headers:{apikey:c.key,Authorization:`Bearer ${s.access_token}`}});}catch{} }
